@once
<style>
.inventory-workspace{display:grid;gap:1.5rem;min-width:0}.inventory-workspace .admin-panel{min-width:0}.inventory-filters{display:grid;grid-template-columns:minmax(0,2fr) repeat(2,minmax(0,1fr)) auto;gap:1rem;align-items:end}.inventory-filters label,.inventory-form label{display:grid;gap:.5rem}.inventory-workspace input,.inventory-workspace select,.inventory-workspace textarea{width:100%;min-width:0;box-sizing:border-box;border:1px solid #d9d2c5;border-radius:0;padding:.8rem;background:#fff;font:inherit;color:#201d19}.inventory-workspace :focus-visible{outline:2px solid #8b733e;outline-offset:3px}.inventory-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}.inventory-metrics article{border:1px solid #d9d2c5;background:#fff;padding:1.25rem;display:grid;gap:.4rem}.inventory-metrics strong{font-size:2rem}.inventory-metrics span,.inventory-muted{color:#706b60;font-size:.9rem}.inventory-table{width:100%;border-collapse:collapse;table-layout:fixed}.inventory-table th{text-align:left;font-size:.76rem;text-transform:uppercase;letter-spacing:.08em;color:#706b60}.inventory-table th,.inventory-table td{padding:1rem .6rem;border-bottom:1px solid #e5dfd4;vertical-align:top;overflow-wrap:anywhere}.inventory-table td small{display:block;margin-top:.35rem;color:#706b60}.inventory-table .inventory-identity{width:27%}.inventory-table .inventory-number{font-variant-numeric:tabular-nums}.inventory-table a{color:inherit}.inventory-stock{display:inline-block;padding:.25rem .5rem;border:1px solid #d9d2c5;font-size:.73rem;text-transform:uppercase;letter-spacing:.05em;background:#f5f2eb}.inventory-stock[data-in-stock="true"]{border-color:#aab29b;color:#35432d;background:#f2f5ed}.inventory-actions{display:flex;justify-content:space-between;align-items:center;gap:1rem;flex-wrap:wrap;margin-top:1.5rem}.inventory-operation-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.inventory-operation-grid .inventory-wide{grid-column:1/-1}.inventory-help{max-width:65ch;line-height:1.65}.inventory-history-heading{display:flex;justify-content:space-between;align-items:center;gap:1rem;flex-wrap:wrap}.inventory-history-heading h2{margin:0}.inventory-product-summary{margin:1.5rem 0}.inventory-product-summary table{margin-top:1rem}
@media(max-width:1024px){.inventory-filters{grid-template-columns:repeat(2,minmax(0,1fr))}.inventory-table th,.inventory-table td{padding:.85rem .35rem}.inventory-table{font-size:.9rem}}
@media(max-width:768px){.inventory-table thead{display:none}.inventory-table,.inventory-table tbody,.inventory-table tr,.inventory-table td{display:block;width:auto}.inventory-table tr{padding:1rem 0;border-bottom:1px solid #d9d2c5}.inventory-table td{display:grid;grid-template-columns:6.5rem minmax(0,1fr);gap:.75rem;padding:.4rem 0;border:0}.inventory-table td::before{content:attr(data-label);font-size:.75rem;color:#706b60;text-transform:uppercase}.inventory-table .inventory-identity{width:auto}.inventory-metrics{gap:.5rem}.inventory-metrics article{padding:.8rem}.inventory-metrics strong{font-size:1.5rem}}
@media(max-width:480px){.inventory-filters,.inventory-operation-grid{grid-template-columns:minmax(0,1fr)}.inventory-actions>a,.inventory-actions>button{width:100%;text-align:center}.inventory-metrics{grid-template-columns:minmax(0,1fr)}.inventory-metrics article{grid-template-columns:1fr auto;align-items:center}.inventory-table td{grid-template-columns:5.5rem minmax(0,1fr)}}
</style>
@endonce
